"question": "次の記述のうち、来客応対における適切な言葉遣いの組み合わせを選べ。\n\nア：来客に対しては「すみません」よりも「恐れ入ります」を用いる\nイ：来客の名前は、確認せずに想像で呼ぶ\nウ：上司への取り次ぎを依頼する際は「少々お待ちくださいませ」と伝える\nエ：来客に対しては、できるだけくだけた言葉で親しみを演出する",
