"answer": 0,
"explanation": "アとイは伝言メモの書き方として適切である。\n\nア：相手の社名・氏名・用件・連絡先を記載することは、伝言メモの基本的な構成要素である。\nイ：受信した日時を記載することで、伝言の緊急性や経過時間を把握できる。\nウ：誤り。伝言を受けた秘書自身の感想は、伝言メモに記載すべき情報ではない。\nエ：誤り。伝言は口頭だけでなく、メモとして記録に残すことが、確実な伝達のために重要である。\n\n【頻出】伝言メモの記載項目は、電話対応の基本知識として頻出のテーマである。\n【関連知識】伝言メモは、上司が確認した後の対応にも活用される重要な記録である。"
